forms.api:
export type RefusalProps = {
	kicker?: string;
	title: string;
	lines: string[];
	principle: string;
};

export function Refusal({ kicker, title, lines, principle }: RefusalProps)

export function Excerpt({
	source,
	heading,
	text,
	trimmed,
	href,
}: {
	/** Which document — evidence voice. */
	source: string;
	/** The section within it. */
	heading?: string;
	/** The verbatim passage (light markdown rendered). */
	text: string;
	/** Whether the passage was cut — shown honestly, never mid-word. */
	trimmed?: boolean;
	/** The whole document, when it lives somewhere linkable. */
	href?: string;
})

export function Answer({
	id,
	question,
	answer,
	cite,
}: {
	/** Stable anchor for deep links (e.g. "gate-up-down"). */
	id?: string;
	/** The question, phrased the way it is actually asked. */
	question: string;
	/** The direct answer — one lift-able paragraph, 40–100 words. */
	answer: string;
	/** Optional source note, e.g. "recorded — granite-4.1-3b · 2026-08-20". */
	cite?: string;
})

export function Snippet({
	label,
	code,
	aside,
}: {
	/** The kicker above the block — what this is, in a few words. */
	label: string;
	/** Verbatim code or output. Rendered as-is, monospace. */
	code: string;
	/** One sentence of context, set quietly beneath the block. */
	aside?: string;
})

export type AnatomyLayer = {
	label: string;
	/** Short mono note, right-aligned in the layer's header — a role, a class number. */
	note?: string;
	/** The explanation — always visible. An anatomy that hides its annotations is a teaser, not a drawing. */
	detail: string;
	/** Named contents of this layer, listed beneath the explanation. */
	children?: AnatomyChild[];
	emphasis?: boolean;
	muted?: boolean;
};

export type AnatomyProps = {
	kicker: string;
	objectLabel: string;
	layers: AnatomyLayer[];
	caption?: string;
};

export function Anatomy({ kicker, objectLabel, layers, caption }: AnatomyProps)

type Part = { label: string; detail: string };

export type DecompositionProps = {
	kicker: string;
	source: Part;
	parts: Part[];
	result: Part;
};

export function Decomposition({ kicker, source, parts, result }: DecompositionProps)

type Scenario = { label: string; activeIndices: number[] };

export type ExpertFieldProps = {
	statement?: string;
	totalUnits: number;
	scenarios: Scenario[];
	caption?: string;
};

export function ExpertField({ statement, totalUnits, scenarios, caption }: ExpertFieldProps)

type Side = { label: string; properties: string[] };

export type ComparisonProps = {
	kicker: string;
	objectLabel: string;
	blockLabels: string[];
	left: Side;
	right: Side;
};

export function Comparison({
	kicker,
	objectLabel,
	blockLabels,
	left,
	right,
}: ComparisonProps)

export type Variant = {
	id: string;
	fidelity: string;
	bytes?: string;
	storage?: string;
	present: boolean;
	/** Relative physical size of this form, 0..1 — drives the drawn area. */
	scale?: number;
	/** Hatch pitch in px — tighter reads as denser packing / lower precision. */
	density?: number;
};

export type VariantsProps = {
	kicker: string;
	/** The identity that never changes and never re-renders. */
	objectLabel: string;
	variants: Variant[];
	baseline: string;
	refusalTitle: string;
	refusalPrinciple: string;
	caption?: string;
};

export function Variants({
	kicker,
	objectLabel,
	variants,
	baseline,
	refusalTitle,
	refusalPrinciple,
	caption,
}: VariantsProps)

export type Rung = {
	id: string;
	question?: string;
	gate?: string;
	status?: "PASSED" | "OPEN" | "BUILDING" | "DISPROVED";
	detail?: string;
};

export type LadderProps = {
	kicker: string;
	rungs: Rung[];
	caption?: string;
};

export function Ladder({ kicker, rungs, caption }: LadderProps)

export type AgreementProps = {
	kicker: string;
	/** The authorities that must agree, in order. */
	columns: { label: string; source: string }[];
	rows: { values: string[]; verdict: "PASS" | "FAIL"; note?: string }[];
	caption?: string;
};

export function Agreement({ kicker, columns, rows, caption }: AgreementProps)

export type DerivationProps = {
	kicker: string;
	/** The graded scale, strongest first. */
	lattice: { level: string; meaning: string }[];
	/** Each cap: what pushes the marker down, and from where to where. */
	steps: { label: string; from: string; to: string }[];
	/** The derived level — where the fold ends. */
	result: string;
	caption?: string;
};

export function Derivation({ kicker, lattice, steps, result, caption }: DerivationProps)

export type ByteField = {
	name: string;
	type: string;
	bytes: number;
	/** A fixed value, when the format pins one (a magic, a version). */
	value?: string;
	meaning: string;
};

export type ByteMapProps = {
	kicker: string;
	title: string;
	fields: ByteField[];
	/** e.g. "24 bytes · little-endian · regions 64-byte aligned" */
	totalLabel?: string;
	caption?: string;
};

export function ByteMap({ kicker, title, fields, totalLabel, caption }: ByteMapProps)

export type TerminalLine = {
	text: string;
	tone?: "accent" | "dim" | "err" | "ok";
	/** Renders the line as a link — the terminal's door into the rest of the site. */
	href?: string;
};

export type TerminalResult = {
	lines: TerminalLine[];
	/** A designed object rendered beneath the lines, with its RAW proof. */
	panel?: TerminalPanel;
	/** Reset the scrollback to the banner instead of appending. */
	clear?: boolean;
	/** Play the refusal sound instead of the tick. */
	refused?: boolean;
};

export function Terminal({
	kicker,
	headline,
	banner,
	prompt = ">",
	seeds = [],
	execute,
	complete,
	autorun,
	notice,
	sessionKey,
	height = 420,
	clearLabel = "CLEAR",
	fallback,
	footnote,
}: {
	/** Evidence-voice label above the instrument. */
	kicker: string;
	/** Editorial-voice line, e.g. "psql, for a model." */
	headline?: string;
	/** The lines a fresh session opens with — also what CLEAR restores. */
	banner: TerminalLine[];
	/** The prompt string, caller-owned (may change between lines). */
	prompt?: string;
	/** One-click statements rendered as chips under the terminal. */
	seeds?: string[];
	/** The meaning of the terminal: one line in, lines out. */
	execute: (line: string) => Promise<TerminalResult> | TerminalResult;
	/** Tab completion: candidate continuations for the current input. */
	complete?: (line: string) => string[];
	/** A command run once on mount — deep links into the terminal. */
	autorun?: string;
	/** Appended (not reset) when it changes — e.g. a transport coming live. */
	notice?: TerminalLine;
	/** When this changes, the scrollback resets to the current banner. */
	sessionKey?: string | number;
	height?: number;
	clearLabel?: string;
	/** System-voice sentences that survive with the interaction removed. */
	fallback?: string;
	/** Evidence-voice closing line. */
	footnote?: string;
})

export type GatingStage = {
	/** The chip label the reader steps with. */
	chip: string;
	/** Editorial-voice reading of the stage. */
	title: string;
	/** System-voice explanation. */
	text: string;
	/** Optional evidence-voice payoff line, rendered in accent. */
	payoff?: string;
	/** Bar width at this stage. */
	width: "narrow" | "wide";
	/** Whether the judgement is visible — unkept channels fade. */
	gated?: boolean;
	/** Evidence-voice label under the bar. */
	label: string;
};

export function Gating({
	stages,
	channels = 24,
	keep,
	fallback,
	footnote,
}: {
	stages: GatingStage[];
	/** How many channel segments the bar draws. */
	channels?: number;
	/** Indices of channels that survive the judgement. */
	keep: number[];
	/** System-voice sentences that survive with the interaction removed. */
	fallback?: string;
	/** Evidence-voice closing line. */
	footnote?: string;
})

export type ProvenanceEvent = { date: string; text: string };

export type ProvenanceProps = {
	/** The published object this page is. One record; four surfaces. */
	record: CitationRecord;
	/** Dated events, newest first — when the work was made, not when the page was touched. */
	history?: ProvenanceEvent[];
	/** Anchor of the Citation block, so the line can offer CITE. */
	citeHref?: string;
	id?: string;
};

export function Provenance({ record, history, citeHref, id }: ProvenanceProps)

export type LensDepth = {
	/** Short, stable, and used as the URL fragment — "learn", "inspect", "spec". */
	id: string;
	label: string;
	/** What this depth gives, in a few words. */
	hint: string;
	content: React.ReactNode;
};

export type LensProps = {
	kicker: string;
	/** The concept being looked at, for the accessible name. */
	concept: string;
	depths: LensDepth[];
	/** Persist the reader's chosen depth across pages. Default true. */
	remember?: boolean;
	caption?: string;
};

export function Lens({ kicker, concept, depths, remember = true, caption }: LensProps)

export type CitationProps = {
	record: CitationRecord;
	/** Anchor — Provenance's CITE link points here. Defaults to "cite". */
	id?: string;
	kicker?: string;
	/** One sentence of context: what exactly is being cited. */
	note?: string;
};

export function Citation({ record, id = "cite", kicker = "CITE THIS", note }: CitationProps)

type Side = { label: string; properties: string[] };

export type TransformationProps = {
	kicker: string;
	objectLabel: string;
	blockLabels: string[];
	from: Side;
	to: Side;
};

export function Transformation({ kicker, objectLabel, blockLabels, from, to }: TransformationProps)

export type CompilationProps = {
	kicker: string;
	headline: string;
	/** Label over the source pile — what you start with. */
	sourceLabel: string;
	sources: string[];
	/** The named stages, lit in order. */
	stages: { name: string; gloss: string }[];
	/** Label over the assembling result. */
	resultLabel: string;
	/** Result rows appear in order during the final stage; an emphasis row is accent-ruled. */
	results: { name: string; emphasis?: boolean; note?: string }[];
	/** The proof mark revealed at the end, in supported green. */
	verifiedLabel: string;
	/** Revealed over the ghosted source pile — why it is no longer needed. */
	discardNote: string;
	/** The whole story in plain words — the always-present fallback. */
	fallback: string;
};

export function Compilation({
	kicker,
	headline,
	sourceLabel,
	sources,
	stages,
	resultLabel,
	results,
	verifiedLabel,
	discardNote,
	fallback,
}: CompilationProps)

export type ProcessionProps = {
	/** Labels for the stages, in order — "layer 0" … "layer 5". */
	stages: string[];
	/** The line revealed under the finished descent. */
	caption: string;
};

export function Procession({ stages, caption }: ProcessionProps)

export type MagnitudeItem = {
	label: string;
	/** The measure, printed beside the label — "4 MB", "≈1.5 TB". */
	sub: string;
	/** The quantity, in any consistent unit. Items must be ascending. */
	magnitude: number;
};

export type MagnitudeProps = {
	items: MagnitudeItem[];
	/** Shown once the sequence rests on the final scale. */
	note?: string;
};

export function Magnitude({ items, note }: MagnitudeProps)

export type ChannelStage = {
	/** Payload density in the stream — wide units move slowly, narrow units arrive more often. */
	density: "wide" | "narrow";
	caption: string;
};

export type ChannelProps = {
	/** The producing endpoint's label — "memory", "disk", "the source". */
	from: string;
	/** The consuming endpoint's label. */
	to: string;
	/** Printed under the conduit — name its fixed capacity. */
	channelLabel: string;
	/** Exactly the stages to play, in order; rests on the last. */
	stages: ChannelStage[];
};

export function Channel({ from, to, channelLabel, stages }: ChannelProps)

export type QuantisationPhase = {
	/** Number of representable levels drawn as grid lines; 0 = the continuum, no grid. */
	levels: number;
	caption: string;
};

export type QuantisationProps = {
	/** Played in order, then held on the last. First phase is usually the continuum. */
	phases: QuantisationPhase[];
	/** The consequence line, revealed at rest — why the snapping matters. */
	note?: string;
	/** Values in (0,1) to display; defaults to a fixed deterministic set. */
	values?: number[];
};

export function Quantisation({ phases, note, values = DEFAULT_VALUES }: QuantisationProps)

export type FilmProps = {
	title: string;
	description: string;
	/** Without src the form renders its designed placeholder frame — slots ship before films exist. */
	src?: string;
	poster?: string;
	/** WebVTT captions track. */
	captions?: string;
};

export function Film({ title, description, src, poster, captions }: FilmProps)
